using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalBakedSurfaceTextures{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity";
static FinalBakedSurfaceTextures(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalBakedSurfaceTextures.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalBakedSurfaceTextures.request");Run();}
static string Ref(UnityEngine.Object o)=>o?AssetDatabase.GetAssetPath(o)+"/"+o.name:"null";
static string Snapshot(Scene scene){var rows=new List<string>();foreach(var go in scene.GetRootGameObjects())foreach(var t in go.GetComponentsInChildren<Transform>(true)){var f=t.GetComponent<MeshFilter>();var r=t.GetComponent<Renderer>();var cols=t.GetComponents<Collider>();rows.Add(t.GetInstanceID()+" "+t.localToWorldMatrix+" mesh="+(f?Ref(f.sharedMesh)+":"+f.sharedMesh.vertexCount:"none")+" mats="+(r?string.Join("|",r.sharedMaterials.Select(Ref)):"none")+" colliders="+string.Join("|",cols.Select(c=>c.GetType().Name+":"+c.GetInstanceID()+(c is MeshCollider?Ref(((MeshCollider)c).sharedMesh):""))));}return string.Join("\n",rows);}
static object Read(MeshFilter f)=>typeof(FinalCitywideStops).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f});
static T Field<T>(object o,string name)=>(T)o.GetType().GetField(name).GetValue(o);
static void Photo(Scene scene,Vector3 p,Vector3 target,string name)=>typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,p,target,name});
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);if(!scene.isLoaded)throw new Exception("Target scene not loaded");string before=Snapshot(scene);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var protectedMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/3D/Fbx/Materials/Pathways.mat");var protectedTex=protectedMat.GetTexture("_BaseMap");string protectedMaterial=EditorJsonUtility.ToJson(protectedMat);var renderers=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();int rendererCount=renderers.Length,materialCount=renderers.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().Count();
foreach(string path in new[]{"Assets/Scenes/Oasis/RoadAtlas/Road Atlas.mat","Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Markings.mat"}){var mat=AssetDatabase.LoadAssetAtPath<Material>(path);var array=mat.GetTexture("_RoadBaseArray") as Texture2DArray;string arrayPath=AssetDatabase.GetAssetPath(array);string guid=AssetDatabase.AssetPathToGUID(path);var settings=AssetDatabase.LoadAssetAtPath<RoadAtlasSources>("Assets/Editor/RoadAtlas/Settings/"+guid+".asset");if(!settings||!File.Exists(arrayPath))throw new Exception("Existing array/settings missing");int width=array.width,height=array.height,depth=array.depth;string surfacePath=AssetDatabase.GetAssetPath(mat.GetTexture("_RoadSurfaceArray"));RoadAtlasTextureBaker.Bake(mat,settings);var updated=mat.GetTexture("_RoadBaseArray") as Texture2DArray;if(AssetDatabase.GetAssetPath(updated)!=arrayPath||updated.width!=width||updated.height!=height||updated.depth!=depth||AssetDatabase.GetAssetPath(mat.GetTexture("_RoadSurfaceArray"))!=surfacePath)throw new Exception("Texture count or layout changed");log.AppendLine("REPACKED existing "+arrayPath+" dimensions="+width+"x"+height+"x"+depth+" Android/iPhone ASTC 4x4; no new arrays");}
if(protectedMaterial!=EditorJsonUtility.ToJson(protectedMat)||protectedTex!=protectedMat.GetTexture("_BaseMap"))throw new Exception("Protected Pathways changed");if(before!=Snapshot(scene))throw new Exception("Scene geometry, materials, transforms or colliders changed");int errors=renderers.SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.shader).Distinct().Sum(s=>ShaderUtil.GetShaderMessages(s).Count(m=>m.severity.ToString()=="Error"));if(errors>0)throw new Exception("Shader errors="+errors);AssetDatabase.SaveAssets();
var marked=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterial&&new[]{"City PNG Markings","Road Atlas"}.Contains(f.GetComponent<Renderer>().sharedMaterial.name)).Select(f=>new{f=f,d=Read(f)}).ToArray();var road=marked.First(v=>v.f.name=="polySurface809");var world=Field<Vector3[]>(road.d,"p");var uv=Field<Vector2[]>(road.d,"uv");var candidates=Enumerable.Range(0,world.Length).OrderBy(i=>Mathf.Abs((uv[i].x-Mathf.Floor(uv[i].x/32)*32-16)-.34f)+Mathf.Abs(Mathf.Repeat(uv[i].y,1)-.5f)).Take(4).Select(i=>world[i]).ToArray();var b=road.f.GetComponent<Renderer>().bounds;Photo(scene,b.center+Vector3.up*24,b.center,"Baked-Road-Manholes");
var corner=marked.First(v=>v.f.name=="polySurface904");var c=corner.f.GetComponent<Renderer>().bounds;Photo(scene,c.center+Vector3.up*35,c.center,"Baked-Junction-Tactile");
var group=root.transform.Find("Citywide Bus Stops - 20");var stop=group.GetChild(0).position;var s=marked.Where(v=>Field<int>(v.d,"layer")==0).OrderBy(v=>v.f.GetComponent<Renderer>().bounds.SqrDistance(stop)).First();var rb=s.f.GetComponent<Renderer>().bounds;var dir=rb.size.x>rb.size.z?Vector3.right:Vector3.forward;var outward=stop-rb.center;outward.y=0;outward=rb.size.x>rb.size.z?new Vector3(0,0,Mathf.Sign(outward.z)):new Vector3(Mathf.Sign(outward.x),0,0);Photo(scene,stop-outward*10+dir*5+Vector3.up*8,stop,"Baked-Pavement-Curb");
log.AppendLine("SUCCESS: four existing source textures edited in place; existing source dimensions and runtime arrays retained; no new scene materials, texture arrays, meshes, lights or draw calls; renderer count="+rendererCount+"; material count="+materialCount+"; Pathways material and assigned texture unchanged; shader errors=0. Details repeat with existing UVs. Source backups stored outside Assets.");File.WriteAllText("FinalSunkenUnderpasses.request","finalcheck");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/BakedSurfaceTexturesReport.txt",log.ToString());}
}
